import{_ as a,o as t,c as r,a4 as i}from"./chunks/framework.2-Vke5-n.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{"sidebarDepth":4,"author":"フューチャー株式会社","layout":"home","hero":{"name":"Web API<wbr>設計ガイドライン","tagline":"Web API Design Guidelines","actions":[{"theme":"brand","text":"WebAPI設計ガイドライン","link":"./web_api_guidelines.md"}]}},"headers":[],"relativePath":"documents/forWebAPI/index.md","filePath":"documents/forWebAPI/index.md"}'),l={name:"documents/forWebAPI/index.md"};function o(n,e,s,c,u,h){return t(),r("div",null,[...e[0]||(e[0]=[i('<h2 id="はじめに" tabindex="-1">はじめに <a class="header-anchor" href="#はじめに" aria-label="Permalink to &quot;はじめに&quot;">​</a></h2><p>本ガイドラインはWeb APIを利用する開発者向けに、RESTライクなWeb APIの主な設計手法をまとめ、システム開発プロジェクトにおける設計のベースラインを提供するために作成された。本ガイドラインを用いることで、開発チームは何を設計すべきか、どのような判断を下すべきかについて共通認識を得ることができる。また、設計の属人性を軽減させ、ナレッジやツールの横展開を容易にすることを狙いにしている。</p><div class="warning custom-block"><p class="custom-block-title">免責事項</p><ul><li>有志で作成したドキュメントである。フューチャーには多様なプロジェクトが存在し、それぞれの状況に合わせて工夫された開発プロセスや高度な開発支援環境が存在する。本ガイドラインはフューチャーの全ての部署 / プロジェクトで適用されているわけではなく、有志が観点を持ち寄って新たに整理したものである</li><li>相容れない部分があればその領域を書き換えて利用することを想定している。プロジェクト固有の背景や要件への配慮は、ガイドライン利用者が最終的に判断すること。本ガイドラインに必ず従うことは求めておらず、設計案の提示と、それらの評価観点を利用者に提供することを主目的としている</li><li>掲載内容および利用に際して発生した問題、それに伴う損害については、フューチャー株式会社は一切の責務を負わないものとする。掲載している情報は予告なく変更する場合がある</li></ul></div><h2 id="前提条件" tabindex="-1">前提条件 <a class="header-anchor" href="#前提条件" aria-label="Permalink to &quot;前提条件&quot;">​</a></h2><p>本ガイドラインの前提は以下の通り。</p><ul><li>gRPC、JSON-RPC、SOAP、GraphQLなど、RPCやグラフ志向ではなく、REST志向のWeb API構築が対象である</li><li>業務システム向け Web API 提供である（サードパーティ向けに広く開発する Web API ではなく、限られたクライアントやシステムと連携すること。いわゆる、LSUDs（Large Set of Unknown Developers）ではなく、SSKDs（Small Set of Known Developers）が対象である</li><li>AWSなどのクラウド環境で構築される</li></ul><p>また、利用者は以下の技術を理解しているとし、本ガイドラインではこれらについて解説はしない。</p><ul><li>基礎的なHTTPの知識</li><li>基礎的なRESTの知識</li></ul><p>また、本ガイドラインの適用範囲は、Web APIのサーバーサイドの設計についてまとめる。クライアントサイドについては対象外とする。</p><h2 id="参考資料" tabindex="-1">参考資料 <a class="header-anchor" href="#参考資料" aria-label="Permalink to &quot;参考資料&quot;">​</a></h2><ul><li><a href="https://learn.microsoft.com/ja-jp/azure/architecture/best-practices/api-design" target="_blank" rel="noreferrer">Web API 設計のベスト プラクティス - Azure Architecture Center</a></li><li><a href="https://learn.microsoft.com/ja-jp/azure/architecture/best-practices/api-implementation" target="_blank" rel="noreferrer">Web API 実装 - Best practices for cloud applications</a></li></ul><h2 id="謝辞" tabindex="-1">謝辞 <a class="header-anchor" href="#謝辞" aria-label="Permalink to &quot;謝辞&quot;">​</a></h2><p>このアーキテクチャガイドラインの作成には多くの方々にご協力いただいた。心より感謝申し上げる。</p><ul><li><strong>作成者</strong>: 真野隼記、佐々木伸悟、武田大輝、宮崎将太、澁川喜規、佐藤尭彰</li><li><strong>レビュアー</strong>: 辻大志郎、合田飛</li></ul><h2 id="articles" tabindex="-1">Articles <a class="header-anchor" href="#articles" aria-label="Permalink to &quot;Articles&quot;">​</a></h2><ul><li>2025.05.13 <a href="https://future-architect.github.io/articles/20250513b/" target="_blank" rel="noreferrer">Web API設計ガイドラインを公開しました</a></li></ul><div class="next-page-nav"><p>次のページ: <a href="./web_api_guidelines.html">Web API設計ガイドライン</a></p></div>',17)])])}const b=a(l,[["render",o]]);export{p as __pageData,b as default};
